// characterClips.js
// Sprite-sheet manifest for the seated character.
// Sheet: public/character/seated-sheet.png, generated by
// scripts/generate_seated_sprite.py (see docs/CHARACTER_SPRITE.md).

export const CHARACTER_SHEET = {
    url: "/character/seated-sheet.png",
    columns: 4,
    rows: 6,
    // Native (pre-upscale) cell size; the PNG is these x4, nearest-neighbour.
    cellWidth: 64,
    cellHeight: 96,
    // Hip centre in native px. The sprite is anchored here (bottom of cell),
    // so it lines up with the chair regardless of the cell padding.
    hipX: 22,
    // World units per native pixel: ~88px figure -> ~2.7 units tall.
    unitsPerPixel: 2.7 / 88,
};

// Each frame:
//   index  sheet cell, row-major (row * 4 + column)
//   hold   seconds on this frame, or [min, max] for a randomised hold
//   mug    optional [x, y, tilt] in native cell pixels: while set, the 3D desk
//          mug leaves the desk and its body centre is held at this point
//          (tilt in radians, toward the face). The mug is never drawn into the
//          sprite artwork.
const TYPE = [0.1, 0.2];

export const CHARACTER_CLIPS = {
    // Row 0
    idle: {
        loop: true,
        frames: [
            { index: 0, hold: [2, 3.5] },
            { index: 1, hold: 0.9 }, // inhale
            { index: 0, hold: [1.2, 2] },
            { index: 3, hold: 0.7 }, // small head tilt
            { index: 2, hold: [2, 3.5] }, // elbow shifts on the desk
            { index: 1, hold: 0.9 },
            { index: 2, hold: [1, 2] },
        ],
    },
    // Row 1
    typing: {
        loop: true,
        frames: [
            { index: 4, hold: TYPE },
            { index: 5, hold: TYPE },
            { index: 6, hold: TYPE },
            { index: 7, hold: TYPE },
            { index: 5, hold: TYPE },
            { index: 4, hold: TYPE },
            { index: 6, hold: [0.3, 0.7] }, // thinking pause
        ],
    },
    // Row 2
    adjustGlasses: {
        frames: [
            { index: 8, hold: 0.16 },
            { index: 9, hold: 0.22 },
            { index: 10, hold: 0.5 }, // pushes the frame up
            { index: 9, hold: 0.14 },
            { index: 11, hold: 0.18 },
        ],
    },
    // Row 3
    lookAtMug: {
        frames: [
            { index: 12, hold: 0.16 },
            { index: 13, hold: 0.3 },
            { index: 14, hold: 0.45 },
            { index: 15, hold: 0.14 }, // hand lifts off the desk
        ],
    },
    // Row 4
    reachMug: {
        frames: [
            { index: 16, hold: 0.12 },
            { index: 17, hold: 0.12 },
            { index: 18, hold: 0.18 },
            { index: 19, hold: 0.25, mug: [57, 32, 0] }, // grip
        ],
    },
    // Row 5
    drink: {
        frames: [
            { index: 20, hold: 0.25, mug: [56, 29, 0] },
            { index: 21, hold: 0.3, mug: [45, 27, 0.35] },
            { index: 22, hold: 1.1, mug: [45, 26, 0.7] }, // sip
            { index: 21, hold: 0.25, mug: [45, 27, 0.35] },
            { index: 23, hold: 0.3, mug: [55, 32, 0] },
        ],
    },
    // Put-down: no dedicated row; the reach frames played in reverse.
    returnMug: {
        frames: [
            { index: 19, hold: 0.3, mug: [57, 32, 0] }, // set it down
            { index: 18, hold: 0.16 }, // release
            { index: 17, hold: 0.12 },
            { index: 16, hold: 0.12 },
            { index: 15, hold: 0.12 },
            { index: 13, hold: 0.25 },
            { index: 12, hold: 0.2 }, // head turns back
        ],
    },
};

// Ambient routine. Looping clips run for `duration`; one-shot clips run
// through their frames once.
export const WORK_CYCLE = [
    { state: "typing", duration: [6, 10] },
    { state: "adjustGlasses" },
    { state: "typing", duration: [5, 9] },
    { state: "idle", duration: [4, 7] },
    { state: "typing", duration: [5, 8] },
    { state: "lookAtMug" },
    { state: "reachMug" },
    { state: "drink" },
    { state: "returnMug" },
    { state: "idle", duration: [3, 5] },
];

// Played when the visitor clicks the mug.
export const DRINK_SEQUENCE = ["lookAtMug", "reachMug", "drink", "returnMug"];

export function hasClip(state) {
    return Object.hasOwn(CHARACTER_CLIPS, state);
}

export function pickDuration(value) {
    if (Array.isArray(value)) {
        return value[0] + Math.random() * (value[1] - value[0]);
    }
    return value;
}
